-- Expand only. No backfill or rewrite of original business records.
CREATE TABLE IF NOT EXISTS contacts(workspace_id uuid NOT NULL,id uuid NOT NULL,display_name text NOT NULL,revision integer NOT NULL CHECK(revision>0),PRIMARY KEY(workspace_id,id));
CREATE TABLE IF NOT EXISTS contact_revisions(workspace_id uuid NOT NULL,contact_id uuid NOT NULL,revision integer NOT NULL,raw_address text NOT NULL,address text NOT NULL,chain_id text NOT NULL CHECK(chain_id='31337'),changed_by uuid NOT NULL REFERENCES users(id),reason text NOT NULL,at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(workspace_id,contact_id,revision),FOREIGN KEY(workspace_id,contact_id) REFERENCES contacts(workspace_id,id));
CREATE TABLE IF NOT EXISTS destination_verifications(workspace_id uuid NOT NULL,id uuid NOT NULL,contact_id uuid NOT NULL,destination_revision integer NOT NULL,actor_id uuid NOT NULL REFERENCES users(id),decision text NOT NULL CHECK(decision IN ('approve','hold')),second_channel_reference text NOT NULL,at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(workspace_id,id),UNIQUE(workspace_id,contact_id,destination_revision),FOREIGN KEY(workspace_id,contact_id,destination_revision) REFERENCES contact_revisions(workspace_id,contact_id,revision));
ALTER TABLE payables ADD COLUMN IF NOT EXISTS contact_id uuid;
ALTER TABLE payables ADD COLUMN IF NOT EXISTS destination_revision integer;
DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM pg_constraint WHERE conname='payable_destination_fk') THEN ALTER TABLE payables ADD CONSTRAINT payable_destination_fk FOREIGN KEY(workspace_id,contact_id,destination_revision) REFERENCES contact_revisions(workspace_id,contact_id,revision); END IF; END $$;
DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM pg_constraint WHERE conname='payable_destination_pair') THEN ALTER TABLE payables ADD CONSTRAINT payable_destination_pair CHECK((contact_id IS NULL)=(destination_revision IS NULL)); END IF; END $$;
CREATE TABLE IF NOT EXISTS payable_revision_history(workspace_id uuid NOT NULL,payable_id uuid NOT NULL,revision integer NOT NULL,snapshot jsonb NOT NULL,actor_id uuid NOT NULL REFERENCES users(id),reason text NOT NULL,at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(workspace_id,payable_id,revision),FOREIGN KEY(workspace_id,payable_id) REFERENCES payables(workspace_id,id));
CREATE TABLE IF NOT EXISTS business_reviews(workspace_id uuid NOT NULL,id uuid NOT NULL,payable_id uuid NOT NULL,payable_revision integer NOT NULL,destination_revision integer NOT NULL,actor_id uuid NOT NULL REFERENCES users(id),reason text NOT NULL,digest text NOT NULL,policy_revision integer NOT NULL CHECK(policy_revision=1),at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(workspace_id,id),FOREIGN KEY(workspace_id,payable_id,payable_revision) REFERENCES payable_revision_history(workspace_id,payable_id,revision));
CREATE TABLE IF NOT EXISTS destination_operation_holds(workspace_id uuid NOT NULL,operation_id uuid NOT NULL,contact_id uuid NOT NULL,destination_revision integer NOT NULL,at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(workspace_id,operation_id,contact_id,destination_revision),FOREIGN KEY(workspace_id,operation_id) REFERENCES treasury_operations(workspace_id,id),FOREIGN KEY(workspace_id,contact_id,destination_revision) REFERENCES contact_revisions(workspace_id,contact_id,revision));
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['contacts','contact_revisions','destination_verifications','payable_revision_history','business_reviews','destination_operation_holds'] LOOP
 EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY',t);EXECUTE format('ALTER TABLE %I FORCE ROW LEVEL SECURITY',t);
 EXECUTE format('DROP POLICY IF EXISTS app_workspace ON %I',t);
 EXECUTE format('CREATE POLICY app_workspace ON %I TO alder_app USING(workspace_id=nullif(current_setting(''alder.workspace_id'',true),'''')::uuid AND EXISTS(SELECT 1 FROM public.memberships m WHERE m.workspace_id=nullif(current_setting(''alder.workspace_id'',true),'''')::uuid AND m.user_id=public.alder_actor())) WITH CHECK(workspace_id=nullif(current_setting(''alder.workspace_id'',true),'''')::uuid AND EXISTS(SELECT 1 FROM public.memberships m WHERE m.workspace_id=nullif(current_setting(''alder.workspace_id'',true),'''')::uuid AND m.user_id=public.alder_actor()))',t);
 EXECUTE format('GRANT SELECT,INSERT ON %I TO alder_app',t);
 IF t<>'contacts' THEN EXECUTE format('DROP TRIGGER IF EXISTS immutable_history ON %I',t);EXECUTE format('CREATE TRIGGER immutable_history BEFORE UPDATE OR DELETE ON %I FOR EACH ROW EXECUTE FUNCTION treasury_immutable()',t);END IF;
 END LOOP;END $$;
GRANT UPDATE(revision) ON contacts TO alder_app;
GRANT UPDATE(contact_id,destination_revision,prepared_by) ON payables TO alder_app;
